const $ = s => document.querySelector(s);
const state = {profile: JSON.parse(localStorage.getItem('bookpilot-profile') || '{"genres":"","avoid":"","length":"any"}'), library: JSON.parse(localStorage.getItem('bookpilot-library') || '[]'), engine: null};
const modelId = 'Qwen2.5-1.5B-Instruct-q4f16_1-MLC';
const genres = {фэнтези:['fantasy','magic'],детектив:['detective','mystery','crime'],роман:['romance','fiction'],ужасы:['horror'],история:['history'],'научная фантастика':['science fiction','space']};
const esc = s => String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const words = s => (s||'').toLowerCase().split(/[,;\s]+/).filter(Boolean);
function save(){localStorage.setItem('bookpilot-profile',JSON.stringify(state.profile));localStorage.setItem('bookpilot-library',JSON.stringify(state.library));$('#library-count').textContent=state.library.length}
function log(text){$('#agent-log').innerHTML='<span class="spark">✦</span><span>'+esc(text)+'</span>'}
function renderLibrary(){const box=$('#library');if(!state.library.length){box.className='library-grid empty-state';box.innerHTML='<h2>Пока здесь пусто</h2><p>Добавьте прочитанную книгу или сохраните рекомендацию.</p>';return}box.className='library-grid';box.innerHTML=state.library.map((b,i)=>'<article class="library-book"><h2>'+esc(b.title)+'</h2><p class="author">'+esc(b.author||'Автор не указан')+'</p><p class="rating">'+('★'.repeat(b.rating||0))+('☆'.repeat(5-(b.rating||0)))+'</p><button class="ghost" data-remove="'+i+'">Удалить</button></article>').join('')}
function plan(q){const l=q.toLowerCase(), n=l.match(/(?:до|менее)\s*(\d{2,4})/);return {q, wanted:Object.keys(genres).filter(x=>l.includes(x)), max:n?+n[1]:(l.includes('коротк')||l.includes('вечер')?300:null)}}
async function search(p){const terms=p.wanted.flatMap(x=>genres[x]).concat(words(state.profile.genres)).filter(Boolean).slice(0,3);const all=[];for(const term of terms.length?terms:['fiction']){const r=await fetch('https://openlibrary.org/search.json?q='+encodeURIComponent(term)+'&limit=15&fields=title,author_name,cover_i,number_of_pages_median,first_publish_year,subject');if(!r.ok)throw Error('Каталог временно недоступен');all.push(...(await r.json()).docs)}return [...new Map(all.filter(x=>x.title).map(x=>[x.title+'|'+(x.author_name?.[0]||''),x])).values()]}
function rank(items,p){const seen=new Set(state.library.map(x=>(x.title+'|'+(x.author||'')).toLowerCase()));return items.map(b=>{const text=(b.title+' '+(b.subject||[]).join(' ')).toLowerCase(),pages=b.number_of_pages_median;let score=10,why=[];const hit=p.wanted.filter(g=>genres[g].some(k=>text.includes(k)));if(hit.length){score+=35;why.push('совпадает с интересом: '+hit.join(', '))}if(p.max&&pages){if(pages<=p.max){score+=20;why.push('около '+pages+' стр. — укладывается в лимит')}else score-=35}if(seen.has((b.title+'|'+(b.author_name?.[0]||'')).toLowerCase()))score=-100;return {...b,score,why:why[0]||'подходит по общему запросу'}}).filter(x=>x.score>-20).sort((a,b)=>b.score-a.score).slice(0,3)}
function cards(items){const box=$('#results');box.className='results';box.innerHTML=items.map((b,i)=>{const cover=b.cover_i?'https://covers.openlibrary.org/b/id/'+b.cover_i+'-M.jpg':'';return '<article class="book-card">'+(cover?'<img class="cover" src="'+cover+'" alt="Обложка">':'<div class="cover"></div>')+'<h2>'+esc(b.title)+'</h2><p class="author">'+esc(b.author_name?.[0]||'Автор не указан')+'</p><p class="meta">'+(b.number_of_pages_median||'Объём не указан')+' стр. · '+(b.first_publish_year||'год неизвестен')+'</p><p class="reason"><strong>Почему:</strong> '+esc(b.why)+'</p><div class="card-actions"><button data-save="'+i+'">Хочу прочитать</button><button data-skip="'+i+'">Не интересно</button></div></article>'}).join('');window.results=items}
async function recommend(){const q=$('#query').value.trim();if(!q){$('#query').focus();return}$('#recommend').disabled=true;log('Планирую поиск, проверяю каталог и вашу историю…');try{const items=rank(await search(plan(q)),plan(q));if(!items.length)throw Error('Точных совпадений не нашлось');cards(items);log('Готово: нашла реальные книги и отобрала подходящие варианты.')}catch(e){$('#results').className='results empty-state';$('#results').innerHTML='<h2>Поиск не удался</h2><p>'+esc(e.message)+'</p>';log('Попробуйте изменить запрос.')}finally{$('#recommend').disabled=false}}
async function loadAI(){const btn=$('#load-model');btn.disabled=true;$('#progress').textContent='Загружаю Qwen2.5 на ваше устройство…';try{const {CreateMLCEngine}=await import('https://esm.run/@mlc-ai/web-llm');state.engine=await CreateMLCEngine(modelId,{initProgressCallback:x=>$('#progress').textContent=x.text||'Загружаю модель…'});$('#model-status').textContent='AI работает локально';$('#model-status').classList.add('ready');btn.textContent='AI включён';$('#progress').textContent='Готово. Модель остаётся в кэше браузера.'}catch(e){btn.disabled=false;$('#progress').textContent='Этот браузер не поддерживает локальный AI. Поиск всё равно работает.'}}
$('#profile-form').addEventListener('submit',e=>{e.preventDefault();state.profile={genres:$('#genres').value,avoid:$('#avoid').value,length:$('#length').value};save();log('Профиль сохранён.')});
$('#recommend').onclick=recommend;$('#load-model').onclick=loadAI;$('#open-add-book').onclick=()=>$('#add-dialog').showModal();
$('#add-book-form').addEventListener('submit',e=>{e.preventDefault();state.library.unshift({title:$('#book-title').value,author:$('#book-author').value,rating:+$('#book-rating').value});save();renderLibrary();$('#add-dialog').close()});
$('#results').onclick=e=>{const b=e.target.closest('button');if(!b||!window.results)return;const i=+(b.dataset.save??b.dataset.skip);if(b.dataset.save!==undefined){const x=window.results[i];state.library.unshift({title:x.title,author:x.author_name?.[0]||'',rating:0});save();renderLibrary();b.textContent='Сохранено';b.disabled=true;log('Книга добавлена в вашу библиотеку.')}else b.closest('.book-card').remove()};
$('#library').onclick=e=>{const b=e.target.closest('[data-remove]');if(b){state.library.splice(+b.dataset.remove,1);save();renderLibrary()}};
document.querySelectorAll('.nav-btn').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav-btn').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));$('#'+b.dataset.view+'-view').classList.add('active')});
$('#genres').value=state.profile.genres||'';$('#avoid').value=state.profile.avoid||'';$('#length').value=state.profile.length||'any';save();renderLibrary();
